import{_ as a}from"./chunks/rules-trigger-de.BglIPUQ6.js";import{_ as t,o as r,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const n="/images/logic-studio/user-guide/rules-walkthrough-fr.jpg",g=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/rules.md","filePath":"fr/projects/logic-studio/user-guide/rules.md","lastUpdated":1795794293000}'),s={name:"fr/projects/logic-studio/user-guide/rules.md"};function l(u,e,c,d,h,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="creer-une-regle-pour-la-lumiere-du-couloir" tabindex="-1">Créer une règle pour la lumière du couloir <a class="header-anchor" href="#creer-une-regle-pour-la-lumiere-du-couloir" aria-label="Permalink to &quot;Créer une règle pour la lumière du couloir&quot;">​</a></h2><h3 id="_1-creer-le-projet" tabindex="-1">1. Créer le projet <a class="header-anchor" href="#_1-creer-le-projet" aria-label="Permalink to &quot;1. Créer le projet&quot;">​</a></h3><p>Choisis <strong>Nouveau projet → Rules</strong>, donne un nom au projet et ouvre l’<strong>assistant</strong>. Il comprend quatre étapes pour le déclencheur, les conditions, les actions et la vérification.</p><h3 id="_2-definir-le-declencheur" tabindex="-1">2. Définir le déclencheur <a class="header-anchor" href="#_2-definir-le-declencheur" aria-label="Permalink to &quot;2. Définir le déclencheur&quot;">​</a></h3><p>Choisis un déclencheur d’état. Saisis l’identifiant de ton capteur de mouvement ou de ta première entrée de test. La démo utilise <code>binary_sensor.bewegung</code>. Saisis <code>on</code> comme état d’arrivée et laisse l’état de départ, l’attribut et la durée minimale vides. Clique sur <strong>Suivant</strong>.</p><p><a href="/images/logic-studio/user-guide/rules-trigger-de.jpg"><img src="'+a+'" alt="Déclencheur d&#39;état dans l&#39;assistant Rules, interface allemande"></a></p><h3 id="_3-passer-les-conditions" tabindex="-1">3. Passer les conditions <a class="header-anchor" href="#_3-passer-les-conditions" aria-label="Permalink to &quot;3. Passer les conditions&quot;">​</a></h3><p>Avance sans ajouter de condition. Une condition sert à vérifier un critère supplémentaire, par exemple l’heure de la journée. Ici, le changement d’état suffit.</p><h3 id="_4-ajouter-une-action" tabindex="-1">4. Ajouter une action <a class="header-anchor" href="#_4-ajouter-une-action" aria-label="Permalink to &quot;4. Ajouter une action&quot;">​</a></h3><p>Dans <strong>ALORS</strong>, ajoute une action HA. Choisis <code>light.turn_on</code> et sélectionne la lampe de test comme cible. Dans la démo, c’est <code>light.flur</code>. Avec une deuxième entrée de test de type interrupteur, utilise <code>input_boolean.turn_on</code>. Laisse <strong>SINON</strong> vide, puis avance.</p><h3 id="_5-verifier-le-yaml" tabindex="-1">5. Vérifier le YAML <a class="header-anchor" href="#_5-verifier-le-yaml" aria-label="Permalink to &quot;5. Vérifier le YAML&quot;">​</a></h3><p>Sous <code>triggers</code>, vérifie l’entité et <code>to: &quot;on&quot;</code>. Sous <code>actions</code>, vérifie l’action et la cible. Applique les réglages, enregistre la règle, puis ouvre-la en YAML HA pour contrôler et exporter le brouillon.</p><h3 id="_6-tester-dans-home-assistant" tabindex="-1">6. Tester dans Home Assistant <a class="header-anchor" href="#_6-tester-dans-home-assistant" aria-label="Permalink to &quot;6. Tester dans Home Assistant&quot;">​</a></h3><p>Ajoute l’automatisation vérifiée à Home Assistant. Mets l’entité déclencheuse à <code>off</code>, puis à <code>on</code>. Vérifie que la bonne cible s’allume. La trace d’automatisation indique quel déclencheur et quelle action ont été exécutés.</p><p><a href="/images/logic-studio/user-guide/rules-walkthrough-fr.jpg"><img src="'+n+'" alt="Éditeur Rules avec le déclencheur d’état dans SI et l’action d’allumage dans ALORS"></a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="assistant-et-palette" tabindex="-1">Assistant et palette <a class="header-anchor" href="#assistant-et-palette" aria-label="Permalink to &quot;Assistant et palette&quot;">​</a></h3><p>L’assistant guide la création. Tu peux aussi chercher et glisser un élément de la palette vers la section voulue.</p><h3 id="declencheurs" tabindex="-1">Déclencheurs <a class="header-anchor" href="#declencheurs" aria-label="Permalink to &quot;Déclencheurs&quot;">​</a></h3><p>Choisis un état avec valeurs avant/après, attribut et durée, un seuil, une heure fixe ou issue d’une entrée, le soleil avec décalage, MQTT, un événement HA ou le démarrage de HA. Les zones et étiquettes regroupent les entités sélectionnées.</p><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><p>Vérifie un état, un nombre, un attribut, une heure ou un jour. ET exige toutes les conditions, OU au moins une et NON inverse le résultat.</p><h3 id="declenche-par" tabindex="-1">Déclenché par <a class="header-anchor" href="#declenche-par" aria-label="Permalink to &quot;Déclenché par&quot;">​</a></h3><p>Donne aux déclencheurs des identifiants comme <code>first</code> et <code>second</code>. Vérifie l’identifiant pour choisir entre ALORS et SINON.</p><h3 id="modele" tabindex="-1">Modèle <a class="header-anchor" href="#modele" aria-label="Permalink to &quot;Modèle&quot;">​</a></h3><p>En mode expert, ajoute une condition de modèle native HA. Son résultat indique si la condition est remplie.</p><h3 id="actions-et-branches" tabindex="-1">Actions et branches <a class="header-anchor" href="#actions-et-branches" aria-label="Permalink to &quot;Actions et branches&quot;">​</a></h3><p>Ajoute les actions dans l’ordre souhaité. Choisis une cible et des paramètres, ajoute un délai, attends un état, appelle un script ou envoie une notification.</p><h3 id="yaml-et-json-rules" tabindex="-1">YAML et JSON Rules <a class="header-anchor" href="#yaml-et-json-rules" aria-label="Permalink to &quot;YAML et JSON Rules&quot;">​</a></h3><p>Utilise le YAML dans HA et le JSON Rules pour rouvrir la règle dans l’éditeur.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Un seuil se déclenche à nouveau après une sortie puis une nouvelle entrée dans la plage.</p>',33)])])}const b=t(s,[["render",l]]);export{g as __pageData,b as default};
